import type { CSSObject } from '@emotion/react';
import styled from '@emotion/styled';
import { Paragraph } from 'components/UI';

export const ContainerGridHolder = styled.div({
  height: '100%',
});

export const WapperGridHolder = styled.div({
  display: 'flex',
  flexDirection: 'column',
});

export const GridHolder = styled.div({
  display: 'grid',
  gridTemplateColumns: 'repeat(3, 1fr)',
  color: '#374151',
  width: '123px',
  rowGap: '0px',

  'p:nth-child(5)': {
    borderRight: '1px solid #E0E0E0',
  },

  'p:nth-child(8)': {
    borderTop: '1px solid #E0E0E0',
    borderRight: '1px solid #E0E0E0',
  },

  'p:nth-child(9)': {
    borderTop: '1px solid #E0E0E0',
  },
});

interface LabelHolderProps {
  $isExportPage?: boolean;
}

export const LabelHolder = styled(Paragraph, {
  shouldForwardProp: (propName) => propName !== '$isExportPage',
})<LabelHolderProps>(({ $isExportPage }) => ({
  textAlign: 'center',
  fontWeight: '400',
  fontSize: '10px',
  lineHeight: '12px',
  color: '#141414',
  ...($isExportPage && {
    fontSize: '14px',
  }),
} as unknown as CSSObject));

interface ValueHolderProps {
  $direction?: 'up' | 'down';
  $isExportPage?: boolean;
}

export const ValueHolder = styled(Paragraph, {
  shouldForwardProp: (propName) =>
    !['$direction', '$isExportPage'].includes(propName),
})<ValueHolderProps>(({ $direction, $isExportPage }) => ({
  textAlign: 'center',
  fontWeight: '600',
  fontSize: '12px',
  lineHeight: '18px',
  color: '#1414148F',
  ...($direction === 'up' && {
    color: '#00810D',
  }),
  ...($direction === 'down' && {
    color: '#A20A0A',
  }),
  ...($isExportPage && {
    fontSize: '14px',
    padding: '0 14px',
  }),
} as unknown as CSSObject));

export const BalancedChoicesFooter = styled(Paragraph)({
  textAlign: 'end',
  fontSize: '10px',
  fontWeight: '400',
  color: '#7B7B7B !important',
  marginRight: '0.55rem',
  height: '24px',
});
